<script setup lang="ts">
import {reactive} from 'vue'
import dayjs from 'dayjs'
import {useAction} from '../hooks/useAction'
import {can} from '../services/session'
import {actionNames,reviewNames,time,money} from '../services/labels'
import MediaInput from '../components/MediaInput.vue'
import MediaPreview from '../components/MediaPreview.vue'
import SignaturePad from '../components/SignaturePad.vue'
import OrderSteps from '../components/OrderSteps.vue'
const model=useAction(),formRef=model.formRef,vm=reactive(model)
</script>
<template><section class="page form-page"><a-alert v-if="vm.error" :message="vm.error" type="error" show-icon /><a-spin :spinning="vm.loading"><template v-if="vm.order"><OrderSteps :status="vm.order.status" /><div class="order-context"><strong>{{vm.order.number}}</strong><p>{{vm.order.description||vm.order.title}}</p></div>
 <a-form ref="formRef" :model="vm.input" :rules="vm.rules" layout="horizontal" @finish="vm.save"><div class="panel form-card"><h2>{{actionNames[vm.action]}}信息</h2>
 <a-form-item v-if="['finish','quote','close'].includes(vm.action)" label="关单类型"><a-select :value="vm.action==='close'?'close':'finish'" :disabled="vm.order.paid||vm.readOnly" :options="[{value:'finish',label:'正常关单'},...can('close')?[{value:'close',label:'非正常关单'}]:[]]" @change="vm.changeType" /></a-form-item>
 <template v-if="vm.action==='quote'||vm.action==='finish'&&vm.order.paid"><a-form-item label="材料费" :name="vm.action==='quote'?'materialAmount':undefined"><a-input-number v-model:value="vm.input.materialAmount" :min="0" :precision="2" :disabled="vm.action==='finish'" /></a-form-item><a-form-item label="人工费" :name="vm.action==='quote'?'artificialAmount':undefined"><a-input-number v-model:value="vm.input.artificialAmount" :min="0" :precision="2" :disabled="vm.action==='finish'" /></a-form-item><p>合计费用：¥ {{money(Number(vm.input.materialAmount||0)+Number(vm.input.artificialAmount||0))}}</p></template>
 <a-form-item v-if="['dispatch','transfer'].includes(vm.action)" label="责任人" name="assignedUserId"><a-select v-model:value="vm.input.assignedUserId" :options="vm.peopleOptions" show-search option-filter-prop="label" placeholder="选择获授权的维修员工" /></a-form-item>
 <template v-if="vm.action==='follow'&&vm.order.status===7||vm.action==='changeLevel'"><a-form-item label="报事等级" name="levelId"><a-select v-model:value="vm.input.levelId" :options="vm.levels" placeholder="请选择报事等级" /></a-form-item></template>
 <template v-if="vm.action==='changeCategory'"><a-form-item label="报事分类" name="categoryId"><a-select v-model:value="vm.input.categoryId" :options="vm.categories" placeholder="请选择第三级分类" /></a-form-item><a-form-item label="报事标签" name="labelIds"><a-select v-model:value="vm.input.labelIds" mode="multiple" :options="vm.labels" /></a-form-item></template>
 <template v-if="vm.action==='delay'"><p>原完成时限：{{time(vm.order.finishDeadline)}}</p><a-form-item label="延期时间至" name="delayUntil"><a-date-picker :value="vm.input.delayUntil?dayjs(vm.input.delayUntil):undefined" show-time @update:value="vm.input.delayUntil=$event?.valueOf()" /></a-form-item></template>
 <template v-if="vm.action==='review'"><a-form-item label="审核申请" name="reviewId"><a-select v-model:value="vm.input.reviewId" :options="vm.eligibleReviews.map(r=>({value:r.id,label:reviewNames[r.kind]+' · '+r.applicantName}))" /></a-form-item><div v-for="r in vm.eligibleReviews.filter(r=>r.id===vm.input.reviewId)" :key="r.id" class="review-context"><p>申请原因：{{r.reason||'—'}}</p><p v-if="r.delayUntil">延期至：{{time(r.delayUntil)}}</p><p v-if="r.targetLevel">目标等级：{{r.targetLevel.name}}</p></div><a-form-item label="审核结果"><a-radio-group v-model:value="vm.input.approved"><a-radio :value="true">通过</a-radio><a-radio :value="false">不通过</a-radio></a-radio-group></a-form-item></template>
 <a-form-item v-if="['delay','abandonApply','changeLevel'].includes(vm.action)||vm.action==='review'&&vm.input.approved===false" :label="vm.reasonLabel" name="reason"><a-textarea v-model:value="vm.input.reason" :rows="3" :maxlength="vm.reasonLimit" show-count /></a-form-item>
 <template v-if="vm.action==='callback'"><a-form-item label="回访方式" name="callbackMethod"><a-radio-group v-model:value="vm.input.callbackMethod"><a-radio v-for="s in ['电话','登门','现场','短信']" :key="s" :value="s">{{s}}</a-radio></a-radio-group></a-form-item><a-form-item label="回访结果" name="callbackResult"><a-radio-group v-model:value="vm.input.callbackResult"><a-radio value="有效">有效</a-radio><a-radio value="无效">无效</a-radio></a-radio-group></a-form-item><a-form-item label="回访人" name="callbackPerson"><a-input v-model:value="vm.input.callbackPerson" :maxlength="128" /></a-form-item><a-form-item label="回访时间" name="callbackTime"><a-date-picker :value="vm.input.callbackTime?dayjs(vm.input.callbackTime):undefined" show-time @update:value="vm.input.callbackTime=$event?.valueOf()" /></a-form-item><a-form-item label="是否返工"><a-radio-group v-model:value="vm.input.rework"><a-radio :value="false">通过</a-radio><a-radio :value="true">返工</a-radio></a-radio-group></a-form-item></template>
 <template v-if="['callback','evaluate','ownerEvaluate'].includes(vm.action)"><a-form-item label="满意度" name="satisfactionId"><a-select v-model:value="vm.input.satisfactionId" :options="vm.satisfaction" /></a-form-item><a-form-item label="评价标签"><a-select v-model:value="vm.input.evaluationLabelIds" mode="multiple" :options="vm.evaluationLabels" /></a-form-item></template>
 <template v-if="['sign','ownerEvaluate'].includes(vm.action)"><a-form-item label="业主姓名" name="ownerName"><a-input v-model:value="vm.input.ownerName" :maxlength="128" /></a-form-item><a-form-item label="业主联系方式" name="ownerPhone"><a-input v-model:value="vm.input.ownerPhone" type="tel" :maxlength="64" /></a-form-item></template>
 <a-form-item v-if="vm.action==='sign'" label="业主签字" name="signatureFileId"><SignaturePad @capture="vm.uploadSignature" /><MediaInput :ids="vm.input.signatureFileId?[vm.input.signatureFileId]:[]" :names="vm.names" :loading="vm.uploading" single @files="vm.uploadSignature($event[0])" @remove="vm.input.signatureFileId=undefined" @preview="vm.openPreview" /></a-form-item>
 <a-form-item v-if="vm.showContent" :label="vm.content.label" name="description"><a-textarea v-model:value="vm.input.description" :rows="4" :maxlength="vm.content.max" :disabled="vm.readOnly" show-count /></a-form-item>
 <a-form-item v-if="['follow','finish','quote','close'].includes(vm.action)" label="回复语" :name="vm.readOnly?undefined:'replyId'"><a-input v-if="vm.readOnly" :value="vm.input.reply" disabled /><a-select v-else v-model:value="vm.input.replyId" :options="vm.replies" /></a-form-item>
 <a-form-item v-if="!['accept','grab','toPaid','sign','changeCategory','changeLevel','delay','abandonApply'].includes(vm.action)" :label="vm.action==='follow'&&vm.order.status===7?'到场照片':'附件'" name="attachmentIds"><MediaInput :ids="vm.input.attachmentIds" :names="vm.names" :loading="vm.uploading" :disabled="vm.readOnly" @files="vm.uploadFiles" @remove="vm.input.attachmentIds=vm.input.attachmentIds.filter(id=>id!==$event)" @preview="vm.openPreview" /></a-form-item>
 </div><div class="form-submit"><a-button type="primary" block html-type="submit" size="large" :loading="vm.saving" :disabled="vm.uploading||vm.loading||!vm.allowed">确认{{actionNames[vm.action]}}</a-button></div></a-form></template></a-spin><MediaPreview :preview="vm.preview" @close="vm.closePreview" /></section></template>
